		{"\x1b[1;5A", CtrlUp, 6},
		{"\x1b[3;5~", CtrlDelete, 6},
		{"\x1b[2~", Insert, 4},
		{"\x1b[200~", BracketedPasteBegin, 6},
		{"\x1b[Z", ShiftTab, 3},
		{"\x1bOA", Up, 3},
		{"\x1b[12;34R", Invalid, 8},
		{"\x1b[?2004;2$y", Invalid, 11},
	} {
