@testset "Mixed signed/unsigned types" begin
    cases = [ # adapted from https://github.com/JuliaLang/julia/pull/59487#issuecomment-3258209203
        (UInt16(100), Int8(-101)),
        (Int8(-50), UInt16(75)),
        (UInt32(12), Int16(-18)),
        (Int64(-24), UInt8(36)),
        (UInt8(15), Int16(-25)),
        (Int32(-42), UInt64(56)),
        (UInt128(1000), Int32(-1500)),
        (UInt64(0), Int32(-5)),
        (Int16(-7), UInt8(0)),
        (Int8(-14), UInt8(13)),
    ]
    for (a, b) in cases
        g1 = gcd(a, b)
        g2, s, t = gcdx(a, b)
        @test g1 === g2
        @test s*a + t*b == g2
        @test g2 >= 0
        @test lcm(a, b) === convert(typeof(g1), lcm(widen(a), widen(b)))
    end

