function _cospi_kernel(x::AbstractFloat, sch)
    x² = x * x
    c₀ = sch.c₀
    (c₂, c₂_lo) = sch.c₂
    rest = sch.rest
    c₂ = -c₂
    c₂_lo = -c₂_lo
    r = evalpoly(x², rest) * x²
    a_x² = c₂ * x²
    a_x²_lo = muladd(c₂_lo, x², muladd(c₂, x², -a_x²))
    w = c₀ - a_x²
    w + muladd(x², r, ((c₀ - w) - a_x²) - a_x²_lo)
end

function _sinpi_kernel(x::AbstractFloat, sch)
    x² = x * x
    (c₁, c₁_lo) = sch.c₁
    (c₃, rest...) = sch.rest
    if rest === ()
        r = typeof(x)(0)
    else
        r = evalpoly(x², rest)
    end
    muladd(c₁, x, x * muladd(c₃, x², muladd(x² * x², r, c₁_lo)))
end

