`uvm_component_utils(ibex_icache_core_monitor)

// the base class provides the following handles for use:
// ibex_icache_core_agent_cfg: cfg
// ibex_icache_core_agent_cov: cov
// uvm_analysis_port #(ibex_icache_core_bus_item): analysis_port

`uvm_component_new

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
endfunction

task run_phase(uvm_phase phase);
  if (cfg.en_cov) begin
    fork
      process_cancelled_valid();
    join_none
  end

  super.run_phase(phase);

  disable fork;
endtask

// collect transactions forever - already forked in dv_base_monitor::run_phase
virtual protected task collect_trans();
  ibex_icache_core_bus_item trans;
  logic                     last_inval = 0;
  logic                     last_enable = 0;
  logic                     last_busy = 0;
  logic [31:0]              last_addr = 'x;

  forever begin
    // Collect events on positive clock edges. We collect "outputs" from the cache first, and then
    // "inputs". This makes the scoreboard's job easier: if a branch is asserted on the same cycle
    // as a fetch happens, the cache is being redirected at the end of the cycle, but the fetch
    // came out of the cache at the start of the cycle. This way, the scoreboard doesn't need to
    // do any re-ordering.
    @(posedge cfg.vif.clk);

    // "Output" transactions

    // Spot whether we've received some instruction data.
    //
    // Note that we ignore anything coming back when we have branch asserted. This can happen if
    // timing happens to work out that way or (more likely) the cycle after we've read an error,
    // when we can keep the ready line high but also assert branch, which means we will ignore
    // what comes back on this cycle.
    if (cfg.vif.ready & cfg.vif.valid & ~cfg.vif.branch) begin
      trans = ibex_icache_core_bus_item::type_id::create("trans");
      trans.trans_type = ICacheCoreBusTransTypeFetch;
      trans.address    = cfg.vif.addr;
      trans.insn_data  = cfg.vif.rdata;
      trans.err        = cfg.vif.err;
      trans.err_plus2  = cfg.vif.err_plus2;
      trans.enable     = 0;
      trans.busy       = 0;
      analysis_port.write(trans);

      if (cfg.en_cov) begin
        if (!$isunknown(last_addr)) cov.on_inc_fetches(last_addr, cfg.vif.addr);
        cov.fetch_cg.sample(cfg.vif.err, cfg.vif.err_plus2, cfg.vif.enable);
      end

// Busy signal from the cache (either there's a request on the bus or the cache is invalidating
// itself)
logic         busy;

// A clocking block for test code that drives the interface
clocking driver_cb @(posedge clk);

  // Drive signals on the following negedge: this isn't needed by the design, but makes it
  // slightly easier to read dumped waves.
  default output negedge;

  output req;

  output branch;
  output branch_addr;

  output ready;
  input  valid;
  input  err;

  output enable;
  output invalidate;
endclocking

// A clocking block for test code that needs to monitor the interface
clocking monitor_cb @(posedge clk);
  input  req;
  input  branch;
  input  branch_addr;
  input  ready;
  input  valid;
  input  rdata;
  input  addr;
  input  err;
  input  err_plus2;
  input  enable;
  input  invalidate;
  input  busy;
endclocking


// SVA module
ibex_icache_core_protocol_checker checker_i (.*);


// Drive the branch pin for a single cycle, redirecting the cache to the given instruction
// address.
task automatic branch_to(logic [31:0] addr);
  driver_cb.branch      <= 1'b1;
  driver_cb.branch_addr <= addr;

  @(driver_cb);

  driver_cb.branch      <= 1'b0;
  driver_cb.branch_addr <= 'X;
endtask

// Raise a pulse on the invalidate line for the given number of cycles.
//
// A one-cycle pulse will start an invalidation, but testing might want a longer pulse (which the
// cache should support)
task automatic invalidate_pulse(int unsigned num_cycles);
  driver_cb.invalidate <= 1'b1;
  wait_clks(num_cycles);
  driver_cb.invalidate <= 1'b0;
endtask

// A task that waits for num_clks posedges on the clk signal. Returns early on reset if
// stop_on_reset is true.
task automatic wait_clks(int num_clks, bit stop_on_reset = 1'b1);
  if (stop_on_reset && !rst_n) return;
  if (stop_on_reset) begin
    fork
      repeat (num_clks) @(driver_cb);
      @(negedge rst_n);
    join_any
    disable fork;
  end else begin
    repeat (num_clks) @(driver_cb);
  end
endtask

// Wait until the valid signal goes high. Returns early on reset
task automatic wait_valid();
  fork
    @(negedge rst_n);
    wait (driver_cb.valid);
  join_any
  disable fork;
endtask

// Reset all the signals from the core to the cache (the other direction is controlled by the
// DUT)
task automatic reset();
  driver_cb.req         <= 1'b0;
  driver_cb.branch      <= 1'b0;
  driver_cb.ready       <= 1'b0;
  driver_cb.enable      <= 1'b0;
  driver_cb.invalidate  <= 1'b0;
endtask


// Coverage properties

// Spot a valid signal being cancelled. This happens when valid was high and the core hasn't taken

            // the maximum possible shift-add operations will be completed regardless of op_b
            // SEC_CM: CORE.DATA_REG_SW.SCA
            md_state_d     = ((!data_ind_timing_i && (op_b_shift_d == 0)) ||
                              (multdiv_count_q == 5'd1)) ? MD_LAST : MD_COMP;
          end
          MD_OP_MULH: begin
            accum_window_d = res_adder_h;
            op_a_shift_d   = op_a_shift_q;
            op_b_shift_d   = op_b_shift_q >> 1;
            md_state_d     = (multdiv_count_q == 5'd1) ? MD_LAST : MD_COMP;
          end
          MD_OP_DIV,
          MD_OP_REM: begin
            accum_window_d = {next_remainder[31:0], op_numerator_q[multdiv_count_d]};
            op_a_shift_d   = next_quotient;
            md_state_d     = (multdiv_count_q == 5'd1) ? MD_LAST : MD_COMP;
          end
          default: ;
        endcase
      end

      MD_LAST: begin
        unique case (operator_i)
          MD_OP_MULL: begin
            accum_window_d = res_adder_l;

            // Note no state transition will occur if multdiv_hold is set
            md_state_d   = MD_IDLE;
            multdiv_hold = ~multdiv_ready_id_i;
          end
          MD_OP_MULH: begin
            accum_window_d = res_adder_l;
            md_state_d     = MD_IDLE;

            // Note no state transition will occur if multdiv_hold is set
            md_state_d   = MD_IDLE;
            multdiv_hold = ~multdiv_ready_id_i;
          end
          MD_OP_DIV: begin
            // this time we save the quotient in accum_window_q since we do not need anymore the
            // remainder
            accum_window_d = next_quotient;
            md_state_d     = MD_CHANGE_SIGN;
          end
          MD_OP_REM: begin
            // this time we do not save the quotient anymore since we need only the remainder
            accum_window_d = {1'b0, next_remainder[31:0]};
            md_state_d     = MD_CHANGE_SIGN;
          end
          default: ;
        endcase
      end

      MD_CHANGE_SIGN: begin
        md_state_d = MD_FINISH;
        unique case (operator_i)
          MD_OP_DIV:
            accum_window_d = div_change_sign ? {1'b0,alu_adder_i} : accum_window_q;
          MD_OP_REM:
            accum_window_d = rem_change_sign ? {1'b0,alu_adder_i} : accum_window_q;
          default: ;
        endcase
      end

      MD_FINISH: begin
        // Note no state transition will occur if multdiv_hold is set
        md_state_d   = MD_IDLE;
        multdiv_hold = ~multdiv_ready_id_i;
      end

      default: begin
        md_state_d = MD_IDLE;
      end
    endcase // md_state_q
  end // (mult_sel_i || div_sel_i)
end


